import "fmt"

func longestConsecutive(nums []int) int {
	values := make(map[int]bool)
	for _, num := range nums {
		values[num] = true
	}
	best := 0
	for num := range values {
		if !values[num-1] {
			length := 1
			for values[num+length] {
				length++
			}
			if length > best {
				best = length
			}
		}
	}
	return best
}

